/**
 * Adopts the UIKit scene life cycle, which the iOS 27 SDK requires.
 *
 * An app built with Xcode 27 that has no scene manifest installs and then dies at
 * launch: UIKit asserts "UIScene life cycle is required for apps built with this SDK".
 * Expo SDK 57 ships the scene delegate for exactly this (`ExpoAppSceneDelegate`, ObjC
 * name `EXExpoAppSceneDelegate`), but its prebuild template does not wire it in — the
 * generated AppDelegate still makes its own window. `ios/` is regenerated by every
 * prebuild, so the wiring lives here rather than as a hand edit that the next
 * `expo prebuild --clean` would silently undo.
 *
 * Two changes, both required together:
 *   1. Info.plist declares one window scene whose delegate is Expo's.
 *   2. AppDelegate conforms to `ExpoReactNativeFactoryProvider` and stops starting React
 *      Native into a window of its own — the scene delegate creates the window from the
 *      connecting scene and starts React Native into it. Starting it in both places
 *      would run the app twice.
 *
 * Remove this plugin once Expo's own template adopts scenes.
 */
const { withInfoPlist, withAppDelegate } = require("expo/config-plugins");

const START_IN_OWN_WINDOW =
  /\n#if os\(iOS\) \|\| os\(tvOS\)\n\s*window = UIWindow\(frame: UIScreen\.main\.bounds\)\n\s*factory\.startReactNative\([\s\S]*?\)\n#endif\n/;

function withSceneLifecycle(config) {
  config = withInfoPlist(config, (cfg) => {
    cfg.modResults.UIApplicationSceneManifest = {
      UIApplicationSupportsMultipleScenes: false,
      UISceneConfigurations: {
        UIWindowSceneSessionRoleApplication: [
          {
            UISceneConfigurationName: "Default Configuration",
            UISceneDelegateClassName: "EXExpoAppSceneDelegate",
          },
        ],
      },
    };
    return cfg;
  });

  config = withAppDelegate(config, (cfg) => {
    if (cfg.modResults.language !== "swift") {
      throw new Error("with-scene-lifecycle expects a Swift AppDelegate.");
    }
    let src = cfg.modResults.contents;

    if (!src.includes("ExpoReactNativeFactoryProvider")) {
      src = src.replace(
        "class AppDelegate: ExpoAppDelegate {",
        "class AppDelegate: ExpoAppDelegate, ExpoReactNativeFactoryProvider {",
      );
    }
    // Fail loudly if the template changed shape: a half-applied edit either runs
    // React Native twice or never starts it, and both look like a blank app.
    if (START_IN_OWN_WINDOW.test(src)) {
      src = src.replace(START_IN_OWN_WINDOW, "\n    // The scene delegate creates the window and starts React Native.\n");
    } else if (src.includes("UIWindow(frame: UIScreen.main.bounds)")) {
      throw new Error("with-scene-lifecycle: AppDelegate template changed; update the plugin.");
    }
    if (!src.includes("ExpoReactNativeFactoryProvider {")) {
      throw new Error("with-scene-lifecycle: could not add ExpoReactNativeFactoryProvider to AppDelegate.");
    }

    cfg.modResults.contents = src;
    return cfg;
  });

  return config;
}

module.exports = withSceneLifecycle;
